const CDQ_DEFAULT_GOOGLE_ACCOUNT_KEY_V2299='cdqDefaultGoogleAccountV2299';
const CDQ_DEFAULT_GOOGLE_ACCOUNT_RESET_V2299='cdqDefaultGoogleAccountResetV2299';

function cdqDefaultGoogleAccountV2299(){
  try{
    if(localStorage.getItem(CDQ_DEFAULT_GOOGLE_ACCOUNT_RESET_V2299)==='1')return '';
    const saved=String(
      localStorage.getItem(CDQ_DEFAULT_GOOGLE_ACCOUNT_KEY_V2299)||
      localStorage.getItem('cdqDefaultGoogleAccountV2294')||
      ''
    ).trim().toLowerCase();
    if(saved)return saved;
  }catch(e){}
  try{return String(utilisateurCourantEmail||'').trim().toLowerCase();}catch(e){return '';}
}
function cdqSetDefaultGoogleAccountV2299(email){
  email=String(email||'').trim().toLowerCase();
  if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw new Error('Adresse Google invalide.');
  try{
    if(email){
      localStorage.setItem(CDQ_DEFAULT_GOOGLE_ACCOUNT_KEY_V2299,email);
      localStorage.setItem('cdqDefaultGoogleAccountV2294',email);
      localStorage.removeItem(CDQ_DEFAULT_GOOGLE_ACCOUNT_RESET_V2299);
    }else{
      localStorage.removeItem(CDQ_DEFAULT_GOOGLE_ACCOUNT_KEY_V2299);
      localStorage.removeItem('cdqDefaultGoogleAccountV2294');
      localStorage.setItem(CDQ_DEFAULT_GOOGLE_ACCOUNT_RESET_V2299,'1');
    }
  }catch(e){}
  try{
    cdqPostToPwa({type:'CDQ_DEFAULT_GOOGLE_ACCOUNT_SET',email:email,reset:!email});
  }catch(e){}
  return email;
}
function cdqMarkOpenedV2299(id){
  if(String(utilisateurCourantRole||'')==='lecture')return;
  fichierOuvertPourModification=id;
  try{
    sessionStorage.setItem('fichierEnModification',id);
    sessionStorage.setItem('ancienneDateModification',(cdqDocumentMeta(id)||{}).dateModification||'');
    sessionStorage.setItem('momentModification',String(Date.now()));
  }catch(e){}
}
function cdqOpenSheetChromeV2299(id){
  const email=cdqDefaultGoogleAccountV2299();
  if(!email)return false;
  cdqMarkOpenedV2299(id);

  // Le parent PWA force Chrome. L'application Sheets native n'est donc
  // jamais lancée lorsque le compte par défaut est actif.
  try{
    if(cdqPostToPwa({
      type:'CDQ_OPEN_SHEET_DEFAULT_ACCOUNT',
      id:String(id||''),
      email:email
    }))return true;
  }catch(e){}

  const url='https://docs.google.com/spreadsheets/d/'+encodeURIComponent(id)+
    '/edit?usp=drivesdk&authuser='+encodeURIComponent(email)+
    '&login_hint='+encodeURIComponent(email);

  if(/Android/i.test(navigator.userAgent||'')){
    window.location.href='intent://docs.google.com/spreadsheets/d/'+encodeURIComponent(id)+
      '/edit?usp=drivesdk&authuser='+encodeURIComponent(email)+
      '&login_hint='+encodeURIComponent(email)+
      '#Intent;scheme=https;package=com.android.chrome;S.browser_fallback_url='+
      encodeURIComponent(url)+';end';
  }else{
    const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';
    document.body.appendChild(a);a.click();a.remove();
  }
  return true;
}

